function validate([words]) {
  if (words.length < 1 || words.length > 100) return 'words needs 1 to 100 strings.';
  for (const word of words) {
    if (word.length < 1 || word.length > 100) return 'Each word has 1 to 100 letters.';
    if (!/^[a-z]+$/.test(word)) return 'Words use only lowercase English letters.';
  }
  return null;
}

