function similarPairs(words) {
  const seen = new Map();
  let pairs = 0;

  for (const word of words) {
    let mask = 0;
    for (const ch of word) {
      mask |= 1 << (ch.charCodeAt(0) - 97);
    }
    const before = seen.get(mask) ?? 0;
    pairs += before;
    seen.set(mask, before + 1);
  }
  return pairs;
}

brute:
function similarPairs(words) {
  const letters = w => [...new Set(w.split(''))].sort().join('');
  let total = 0;
  for (let i = 0; i < words.length; i++)
    for (let j = i + 1; j < words.length; j++)
      if (letters(words[i]) === letters(words[j])) total++;
  return total;
}

