function generate(rand, size) {
  const count = size === 'large' ? 100 : 1 + Math.floor(rand() * 8);
  const maxLength = size === 'large' ? 100 : 5;
  // A small alphabet makes similar words common; sometimes use all 26 letters.
  const alphabet = rand() < 0.2 ? 26 : 2 + Math.floor(rand() * 4);
  const words = [];
  for (let i = 0; i < count; i++) {
    const length = 1 + Math.floor(rand() * maxLength);
    let word = '';
    for (let k = 0; k < length; k++) word += String.fromCharCode(97 + Math.floor(rand() * alphabet));
    words.push(word);
  }
  return [words];
}
